## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Question Is Asked
This problem evaluates the ability to extend classic DP patterns (like the staircase problem) with an additional resource dimension, while also testing space optimization skills and recursive thinking via memoization. It distinguishes candidates who understand both bottom-up and top-down approaches, and who reason through edge cases systematically.

## Key Concepts
- DP with an extra budget constraint (two-dimensional state: position + accumulated cost)
- Space optimization using rolling arrays to reduce O(n·B) space to O(B)
- Memoization on composite state (i, b) for the recursive variant
- Correct base case handling when starting from a virtual position before index 0

## Code Example
```javascript
const MOD = 1_000_000_007n;

function countWays(cost, B) {
  const n = cost.length;
  if (n === 0) return 0;

  // bottom-up with rolling arrays
  let prev2 = new Array(B + 1).fill(0);
  let prev1 = new Array(B + 1).fill(0);

  // base: step 0
  if (cost[0] <= B) prev2[cost[0]] = 1;

  // base: step 1
  if (n > 1 && cost[1] <= B) prev1[cost[1]] = 1;

  // step 2 onwards
  for (let i = 2; i < n; i++) {
    const cur = new Array(B + 1).fill(0);
    for (let b = cost[i]; b <= B; b++) {
      cur[b] = (prev1[b - cost[i]] + prev2[b - cost[i]]) % MOD;
    }
    prev2 = prev1;
    prev1 = cur;
  }

  return n === 1 ? prev2[B] : prev1[B];
}

// memoized DFS variant
function countWaysDFS(cost, B) {
  const n = cost.length;
  const memo = new Map();

  function dfs(i, b) {
    if (b < 0) return 0;
    if (i < 0) return b === 0 ? 1 : 0;
    const key = `${i},${b}`;
    if (memo.has(key)) return memo.get(key);
    const result = (dfs(i - 1, b - cost[i]) + dfs(i - 2, b - cost[i])) % MOD;
    memo.set(key, result);
    return result;
  }

  return dfs(n - 1, B);
}
```

